import { INIT_NEEDS_YES_OR_TERMINAL } from "./plan.js";
import { canPickAgentsInteractively } from "../utils/agent_picker.js";
import { NEON_PLUGIN_NAME } from "../plugins/run.js";
import prompts from "prompts";
//#region src/init/wizard.ts
const restoreCursorOnAbort = (state) => {
	if (state.aborted) {
		process.stdout.write("\x1B[?25h");
		process.stdout.write("\n");
		process.exit(1);
	}
};
const pickAgentSetupInteractively = async () => {
	if (!canPickAgentsInteractively()) throw new Error(INIT_NEEDS_YES_OR_TERMINAL);
	const { setup } = await prompts({
		onState: restoreCursorOnAbort,
		type: "select",
		name: "setup",
		message: "How should coding agents get Neon in this project?",
		initial: 0,
		choices: [
			{
				title: "Plugin (recommended)",
				value: "plugin",
				description: `Install ${NEON_PLUGIN_NAME} (skills and MCP in one)`
			},
			{
				title: "Skills and MCP separately",
				value: "skills-mcp",
				description: "Install skills, then the MCP server"
			},
			{
				title: "Skip agent setup",
				value: "skip",
				description: "Continue without a plugin, skills, or MCP"
			}
		]
	});
	if (setup !== "plugin" && setup !== "skills-mcp" && setup !== "skip") throw new Error("Aborted.");
	return setup;
};
//#endregion
export { pickAgentSetupInteractively };
